      hu: ["Kőolajtermékek exportja.", "Közvetlenül a finomítóhoz kapcsolódik."],
      ro: ["Export de produse petroliere.", "Conectat direct la rafinărie."],
      en: ["Export of petroleum products.", "Directly connected to the refinery."]
